      "explanation": "Cystic fibrosis (CF) is a genetic disorder caused by a defective CFTR protein, which functions as a chloride channel. In most exocrine glands, such as those in the lungs and pancreas, the defective CFTR channel prevents chloride from being secreted into the lumen of the duct. This leads to increased sodium and water reabsorption from the ductal fluid, resulting in thick, viscous, dehydrated secretions that cause obstruction. This obstruction leads to bronchiectasis in the lungs and exocrine insufficiency in the pancreas. The sweat gland is a unique exception. Here, the CFTR channel's primary role is to reabsorb chloride from the sweat as it passes through the sweat duct. In CF, this reabsorptive function is lost. As a result, chloride remains trapped in the sweat, leading to the secretion of sweat with an abnormally high salt concentration. The duct itself is not obstructed; rather, its reabsorptive function is impaired. This is the physiological basis for the diagnostic sweat chloride test.",
