      "explanation": "Peristalsis is the coordinated, wave-like muscular contraction that propels food (bolus) in an antegrade (forward) direction through the gastrointestinal tract. This process is controlled by the enteric nervous system. The peristaltic reflex involves coordinated contraction and relaxation. The contraction of the circular muscle behind (oral to) the bolus is mediated by excitatory motor neurons. The primary excitatory neurotransmitter released by these neurons to cause muscle contraction is acetylcholine (ACh), which acts on muscarinic receptors on the smooth muscle cells. Substance P also plays a co-excitatory role. Simultaneously, the circular muscle ahead of (aboral to) the bolus must relax to allow the bolus to move forward. This relaxation is mediated by inhibitory motor neurons, which primarily release nitric oxide (NO) and Vasoactive Intestinal Peptide (VIP). Therefore, while multiple neurotransmitters are involved, the propulsive contraction itself is primarily mediated by acetylcholine.",
