      "correct": "C",
      "answerText": "(C) Peroxisome",
      "explanation": "Zellweger syndrome is the most severe of a group of genetic disorders known as peroxisome biogenesis disorders (PBDs). It is an autosomal recessive condition caused by mutations in PEX genes, which encode proteins (peroxins) that are essential for the normal formation and assembly of peroxisomes. Peroxisomes are vital cellular organelles that are responsible for several key metabolic functions, including the beta-oxidation of very long-chain fatty acids (VLCFAs), the synthesis of plasmalogens (essential components of myelin), and the metabolism of branched-chain fatty acids. The absence or dysfunction of peroxisomes in Zellweger syndrome leads to the accumulation of toxic VLCFAs and other metabolites in various tissues, particularly the brain, liver, and kidneys. This results in a devastating multisystem disease characterized by severe neurological abnormalities, craniofacial dysmorphism, and liver dysfunction, which is typically fatal in the first year of life.",
