      "answerText": "(D) Arginine",
      "explanation": "The amino acid arginine is a common precursor for the synthesis of all three listed molecules : urea, creatinine, and nitric oxide.\n1. Urea : In the urea cycle, the enzyme arginase acts on arginine to cleave it into urea and ornithine. This is the final step of the cycle, which disposes of excess nitrogen.\n2. Creatinine : Arginine and glycine react to form guanidinoacetate. This compound is then methylated (using SAM-e) to form creatine. Creatine is phosphorylated in muscle to form the high-energy compound phosphocreatine. Phosphocreatine spontaneously and non-enzymatically cyclizes to form creatinine, which is then excreted by the kidneys.\n3. Nitric Oxide : The enzyme nitric oxide synthase (NOS) uses arginine as its substrate, converting it into nitric oxide and citrulline.\nTherefore, arginine serves as a central metabolic hub, providing the guanidinium group or backbone for the synthesis of these three important biological compounds.",
