      "correct": "A",
      "answerText": "(A) ApoE4",
      "explanation": "The gene for Apolipoprotein E (APOE) exists in three common alleles : ε2, ε3, and ε4, which code for the ApoE2, ApoE3, and ApoE4 protein isoforms, respectively. While ApoE's primary role is in lipid transport, it is also involved in neuronal repair and amyloid-beta peptide metabolism in the brain. The ApoE4 allele is the single most important and well-established genetic risk factor for the development of late-onset (sporadic) Alzheimer's disease. Individuals who inherit one copy of the ApoE4 allele have approximately a 3-fold increased risk of developing the disease, while those who inherit two copies (homozygotes) have a 10- to 15-fold increased risk and an earlier age of onset. The ApoE4 isoform is thought to contribute to Alzheimer's pathology by impairing the clearance of amyloid-beta from the brain and promoting its aggregation into toxic plaques. In contrast, the ApoE2 allele appears to be protective.",
