      "answerText": "(D) Crystalline cholesterol monohydrate.",
      "explanation": "The most common type of gallstones found in Western populations are cholesterol gallstones. These form when the bile in the gallbladder becomes supersaturated with cholesterol. Normally, cholesterol is kept soluble in bile through the formation of micelles with bile salts and phospholipids. When the concentration of cholesterol exceeds the solubilizing capacity of the bile, it can no longer remain in solution and begins to precipitate out. This initial step involves the nucleation of cholesterol molecules from the supersaturated bile. These molecules then aggregate and grow into macroscopic stones. The chemical form of the cholesterol that precipitates is anhydrous cholesterol, which then rapidly converts to stable crystalline cholesterol monohydrate. These plate-like crystals are the fundamental building blocks of cholesterol gallstones. Examination of the stones reveals these characteristic cholesterol monohydrate crystals.",
