      "correct": "D",
      "answerText": "(D) Peptidyl Transferase",
      "explanation": "A ribozyme is a ribonucleic acid (RNA) molecule that possesses catalytic activity, meaning it can function as an enzyme. While most biological catalysts are proteins, certain RNA molecules can also catalyze chemical reactions. The most prominent and fundamental example of a ribozyme is the large ribosomal RNA (rRNA) component of the ribosome. The crucial step of protein synthesis, the formation of a peptide bond between amino acids, is catalyzed not by a ribosomal protein but by the peptidyl transferase center located within the 23S (in prokaryotes) or 28S (in eukaryotes) rRNA of the large ribosomal subunit. This discovery that RNA could act as a catalyst was a major breakthrough in molecular biology and led to the RNA world hypothesis. The other options are all protein enzymes : poly(A) polymerase, ribonuclease, and transpeptidase.",
