      "answerText": "(A) Fumarate",
      "explanation": "Aspartate is the amino acid that links the Krebs (TCA) cycle and the urea cycle. The connection between these two cycles is known as the aspartate–argininosuccinate shunt.\nIn the urea cycle, aspartate combines with citrulline to form argininosuccinate in a reaction catalyzed by argininosuccinate synthetase. This step is important because aspartate donates the second nitrogen that ultimately becomes part of urea.\nAspartate itself is formed from oxaloacetate, a key intermediate of the Krebs cycle. Oxaloacetate undergoes transamination (usually with glutamate) to produce aspartate. After argininosuccinate is cleaved in the urea cycle, fumarate is produced as a byproduct. Fumarate then re-enters the Krebs cycle, where it is converted to malate and then back to oxaloacetate, completing the link between the two cycles.\nAlthough fumarate connects to the Krebs cycle, it is not an amino acid. Therefore, aspartate is the correct answer because it directly participates in both cycles and carries nitrogen from amino acid metabolism into the urea cycle.",
