      "correct": "A",
      "answerText": "(A) Cells of Ito",
      "explanation": "The liver is the primary storage organ for Vitamin A in the body, holding up to 80% of the body's total reserves. Within the liver, the storage is highly compartmentalized. The principal storage site for Vitamin A (in the form of retinyl esters) is a specialized cell type located in the perisinusoidal Space of Disse. These cells are known as hepatic stellate cells, or eponymously as Ito cells. These cells take up retinol from the circulation and esterify it for storage within characteristic lipid droplets in their cytoplasm. When needed, they can hydrolyze these esters and release retinol back into the circulation, bound to retinol-binding protein (RBP), which is synthesized by hepatocytes. While hepatocytes play a key role in Vitamin A metabolism (synthesizing RBP), the main storage depot is the Ito cell.",
