      "correct": "B",
      "answerText": "(B) Decreased GpIIb/IIIa",
      "explanation": "Glanzmann thrombasthenia is a rare, autosomal recessive bleeding disorder characterized by a qualitative or quantitative defect in platelet function. The underlying molecular pathology is a deficiency or dysfunction of the glycoprotein IIb/IIIa (GpIIb/IIIa) receptor on the surface of platelets. This receptor is an integrin that, upon platelet activation, undergoes a conformational change and becomes the binding site for fibrinogen. Fibrinogen then acts as a bridge, cross-linking adjacent platelets to one another. This cross-linking is the essential final step in the formation of a stable platelet aggregate and primary hemostatic plug. In Glanzmann thrombasthenia, the absence of functional GpIIb/IIIa receptors means that platelets can adhere to injured endothelium but cannot aggregate. This leads to a severe bleeding tendency, typically manifesting as mucocutaneous bleeding such as epistaxis, gingival bleeding, and menorrhagia. A decreased GpIb (A) is seen in Bernard-Soulier syndrome, while anti-GpIIb/IIIa antibodies (C) are found in immune thrombocytopenic purpura.",
