      "correct": "C",
      "answerText": "(C) Inhibition of elastase",
      "explanation": "Alpha-1 antitrypsin (AAT) is a serine protease inhibitor (serpin) that is primarily synthesized in the liver. Despite its name, its most important physiological role is not the inhibition of trypsin, but rather the inhibition of neutrophil elastase. Neutrophil elastase is a powerful proteolytic enzyme that is released by neutrophils at sites of inflammation to help degrade bacteria and cellular debris. However, if left unchecked, this enzyme can also cause significant damage to host tissues, particularly the delicate elastin fibers in the alveolar walls of the lungs. AAT circulates in the blood and diffuses into tissues, where it binds to and irreversibly inactivates neutrophil elastase, thereby protecting the lungs from proteolytic damage. In individuals with a genetic deficiency of AAT, this protective screen is lost, leading to unopposed elastase activity and the progressive destruction of alveolar walls, resulting in early-onset panacinar emphysema.",
