      "correct": "A",
      "answerText": "(A) Albinism",
      "explanation": "The mode of inheritance describes how a genetic trait or disorder is passed through families. Oculocutaneous albinism is a classic example of an autosomal recessive disorder. It is caused by mutations in genes involved in the synthesis of melanin pigment, most commonly the tyrosinase gene. For a person to be affected, they must inherit two copies of the mutated gene, one from each of their carrier parents. Individuals who inherit only one copy of the mutation are unaffected carriers. In contrast, the other conditions listed are all classic examples of autosomal dominant disorders. Huntington's syndrome, Marfan's syndrome, and Neurofibromatosis type 1 are all caused by a mutation in a single copy of the respective gene. In these disorders, an affected individual has a 50% chance of passing the condition on to each of their children, and the trait typically appears in every generation (vertical transmission).",
