      "correct": "C",
      "answerText": "(C) Crypt abscess",
      "explanation": "Ulcerative colitis and Crohn's disease are both inflammatory bowel diseases, but they differ histologically.\nCrypt abscesses are a characteristic microscopic feature of ulcerative colitis (UC). A crypt abscess forms when neutrophils accumulate within the glandular crypts of the colonic mucosa. In UC, inflammation is typically continuous and confined to the mucosa and submucosa, beginning in the rectum and extending proximally. The mucosa shows ulceration, gland distortion, and frequent crypt abscess formation.\nIn contrast, Crohn’s disease shows transmural inflammation, meaning it involves the entire bowel wall thickness. It is characterized by skip lesions, fissures, fistulas, and noncaseating granulomas. Lymphoid aggregates may be present in Crohn’s disease but are not specific. Mucosal edema and pseudopolyps can occur in both conditions and therefore are not distinguishing features.\nThus, among the given options, crypt abscess is the most specific histologic finding that differentiates ulcerative colitis from Crohn’s disease.",
