      "correct": "A",
      "answerText": "(A) Chylomicron",
      "explanation": "Lipoprotein lipase (LPL) is a critical enzyme located on the surface of capillary endothelial cells in adipose tissue, muscle, and other peripheral tissues. Its primary function is to hydrolyze the triglycerides carried by triglyceride-rich lipoproteins, namely chylomicrons and VLDL. Chylomicrons are synthesized by intestinal enterocytes specifically to transport dietary fat (triglycerides) absorbed from a meal into the circulation. In a patient with a genetic deficiency of LPL (or its cofactor, ApoC-II), this essential clearance mechanism is non-functional. As a result, after consuming a fatty meal, the newly formed chylomicrons cannot be broken down and removed from the bloodstream. This leads to a massive and persistent accumulation of chylomicrons in the plasma, resulting in extreme hypertriglyceridemia (often with milky-appearing plasma) and a high risk of acute pancreatitis.",
