      "explanation": "Wilson's disease is a genetic disorder caused by mutation of the ATP7B gene, leading to impaired copper transport and decreased incorporation of copper into ceruloplasmin. As a result:\n1. Copper accumulates in the liver, brain, and cornea\n2. Serum ceruloplasmin levels decrease\n3. Urinary copper excretion increases (due to excess free copper)\nThe key laboratory feature is increased urinary copper, not decreased excretion of amino acids.\nThe substances listed:\n1. Serine\n2. Methyl-histidine\n3. Phosphotyrosine\nare not characteristically decreased in urine in Wilson’s disease.\nAlthough renal tubular dysfunction (Fanconi-like syndrome) may occur in Wilson’s disease and can actually cause increased urinary amino acid loss, none of the listed substances are specifically decreased.\nTherefore, the correct answer is : (D) None of the Above",
