      "answerText": "(A) Tolvaptan",
      "explanation": "The Syndrome of Inappropriate Antidiuretic Hormone (SIADH) is characterized by excessive secretion of ADH (vasopressin), leading to impaired water excretion and resultant euvolemic hyponatremia. The goal of treatment is to correct the hyponatremia. The most specific pharmacological approach is to block the action of ADH at its receptor in the kidney. Tolvaptan is an orally active, selective vasopressin V2-receptor antagonist. By blocking the V2 receptor in the collecting ducts, tolvaptan prevents the ADH-mediated insertion of aquaporin-2 water channels into the apical membrane. This makes the collecting duct impermeable to water, leading to the excretion of free water (aquaretic effect). This loss of free water raises the serum sodium concentration, directly correcting the hyponatremia of SIADH. In contrast, desmopressin (B) and terlipressin (D) are vasopressin agonists and would worsen the condition.",
