      "correct": "A",
      "answerText": "(A) Apraclonidine",
      "explanation": "Apraclonidine is a topical ophthalmic medication used for the short-term reduction of intraocular pressure (IOP). Its primary mechanism of action is as a relatively selective alpha-2 adrenergic agonist. When applied to the eye, apraclonidine stimulates alpha-2 receptors in the ciliary body. This stimulation leads to a decrease in the production of aqueous humor, which is the primary mechanism by which it lowers IOP. It may also have a secondary effect of increasing uveoscleral outflow. Apraclonidine and the more selective alpha-2 agonist, brimonidine, are an important class of drugs used in the treatment of glaucoma. Timolol (B) is a beta-blocker. Prostaglandin analogues (C) act on prostaglandin receptors. Verapamil (D) is a calcium channel blocker.",
