      "correct": "D",
      "answerText": "(D) All of the above",
      "explanation": "Fixed-dose combinations (FDCs) contain two or more active drugs in a single dosage form. They are commonly used in chronic diseases such as tuberculosis, HIV, hypertension, and diabetes.\nOne benefit is that FDCs can increase efficacy. When drugs with different mechanisms of action are combined, they may produce additive or synergistic therapeutic effects. This is especially important in infections like tuberculosis and HIV, where combination therapy also reduces the risk of drug resistance.\nFDCs may also decrease adverse effects in certain situations. Because each drug can be used at a lower dose than if given alone, dose-related side effects may be reduced. Additionally, combining drugs can sometimes balance unwanted effects.\nThe most significant advantage is that FDCs improve patient compliance. By reducing the number of pills and simplifying treatment regimens, patients are more likely to take their medications regularly, leading to better disease control and outcomes.\nTherefore, all the listed statements are correct, making (D) All of the above the best answer.",
