      "explanation": "Rheumatoid arthritis is treated using a stepwise, treat-to-target approach aimed at achieving remission or low disease activity.\nMethotrexate is the first-line DMARD (disease-modifying antirheumatic drug). If a patient has been on methotrexate, steroids, and NSAIDs for several months without adequate improvement, the next recommended step is to escalate conventional DMARD therapy before moving to biologics.\nAdding another conventional synthetic DMARD such as sulfasalazine (often part of “triple therapy”: methotrexate + sulfasalazine + hydroxychloroquine) is an evidence-based next step. This combination is effective and cost-efficient.\nWhy not the others?\n(A) Anti-TNF monotherapy: Biologics are usually added after failure of combination conventional DMARD therapy, not immediately as monotherapy.\n(B) Continue same treatment: Inadequate response requires escalation.\n(C) Switch to parenteral methotrexate: Useful if absorption or intolerance is suspected, but lack of response suggests need for combination therapy.\nTherefore, the most appropriate next step is : (D) Add sulfasalazine",
