      "number": 106,
      "statement": "Variation in how individuals respond to different doses of a drug is determined using which type of data?",
      "options": [
        "Dose response curve",
        "Therapeutic index",
        "Bioavailability",
        "Phase 1 clinical trials"
      ],
      "correct": "A",
      "answerText": "(A) Dose response curve",
      "explanation": "A quantal dose-response curve is a graph that plots the percentage of a population of individuals that responds to a specific drug effect against the log of the dose administered. This type of curve is used to examine the variation in sensitivity to a drug across a population. It allows for the determination of key parameters like the ED₅₀ (the dose that produces the desired effect in 50% of the population). The slope of the curve indicates the degree of variability; a steep slope means that most individuals respond to a narrow range of doses, while a shallow slope indicates a large variation in sensitivity, with some individuals responding to very low doses and others requiring very high doses. This information is crucial for determining the appropriate starting dose and dose range for a drug in clinical practice. The therapeutic index is a measure of drug safety, not variability.",
