      "explanation": "Rigor mortis is the postmortem stiffening of muscles due to depletion of ATP, leading to sustained actin–myosin cross-linking. It typically begins within 1–2 hours after death.\nAlthough rigor mortis is first noticeable externally in small muscles such as the eyelids and jaw, the earliest onset actually occurs in the myocardium (heart muscle). The myocardium has high metabolic activity and rapid ATP depletion after death, causing it to stiffen earlier than skeletal muscles.\nHowever, this cardiac rigor is not externally visible. Clinically and forensically, rigor mortis is first observed in the smaller voluntary muscles—especially the eyelids, followed by the jaw, neck, upper limbs, trunk, and lower limbs—following Nysten’s law (head to toe progression).\nThus:\n1. Earliest overall onset → Myocardium\n2. Earliest externally visible sign → Eyelids\nSince the question asks which part shows the earliest onset, the correct answer is : (B) Myocardium",
