      "explanation": "Gastric lavage (stomach wash) is generally contraindicated after the ingestion of corrosive substances like strong mineral acids (HCl, H₂SO₄, Nitric acid) or strong alkalis. The reason for this contraindication is the high risk of re-exposing the esophageal and pharyngeal mucosa to the corrosive agent during the procedure, and the potential for causing iatrogenic perforation of the already damaged esophagus or stomach with the lavage tube. However, carbolic acid (phenol) is an exception to this rule. While it is a corrosive, it primarily causes coagulation necrosis and has a significant systemic toxicity (causing CNS depression, seizures, and cardiotoxicity) that results from its rapid absorption. The risk of life-threatening systemic toxicity from absorbed phenol outweighs the risk of the lavage procedure itself. Therefore, gentle gastric lavage is often recommended after carbolic acid ingestion to remove any unabsorbed poison and reduce the systemic toxic load, ideally using a protective liquid like olive oil or castor oil.",
