      "explanation": "When viscera (internal organs) are collected during a postmortem examination for toxicological analysis, it is crucial to preserve them in a solution that prevents decomposition without interfering with the chemical tests for poisons. The standard preservative used for this purpose in India and many other regions is rectified spirit, which is a highly concentrated ethanol solution (approximately 95% alcohol by volume). Ethanol is an effective preservative that prevents bacterial putrefaction of the tissues. Importantly, it is chemically neutral and does not interfere with the standard extraction and detection methods for most common poisons. In contrast, formalin (C) is an excellent preservative for histopathology but is absolutely contraindicated for toxicology, as it denatures proteins and can interfere with the chemical analysis of many toxins. A saturated salt solution can be used if rectified spirit is unavailable, but the latter is the standard.",
