      "explanation": "The findings described are all characteristic features of a gunshot entry wound fired from a close range.\nBurning (searing) is caused by the hot gases from the muzzle of the gun contacting the skin, which only occurs at contact or very close range.\nBlackening (soot deposition) is the deposit of carbon soot on the skin, which is easily wiped away. It indicates a firing distance within about 30 cm.\nTattooing (stippling) is the embedding of unburnt or partially burnt gunpowder particles into the skin, which cannot be wiped away. It is seen in shots fired from an intermediate range (up to about 60 cm).\nA dirt collar (or abrasion collar) is a ring of abraded skin around the entry hole caused by the friction and indentation of the spinning bullet as it enters the skin.\nThe combination of all these features—especially the burning, blackening, and tattooing—definitively identifies the wound as an entry wound fired from a close range. Exit wounds (B, D) do not have these features.",
