      "explanation": "Battered Baby Syndrome, a form of non-accidental injury or child abuse, is a clinical diagnosis based on a pattern of injuries that are inconsistent with the provided history. One of the most classic and pathognomonic cutaneous findings is the presence of multiple bruises in different stages of healing. The age of a bruise can be estimated by its color (e.g., fresh bruises are reddish-purple, older ones become greenish, then yellowish-brown). Finding bruises of various colors on a child indicates that the injuries were inflicted at different times, which is a strong indicator of repeated trauma and is highly suggestive of abuse. Furthermore, bruises in specific locations, such as on the torso, ears, or neck of a non-ambulatory infant, are also highly suspicious. While single injuries can be accidental, this pattern of repeated injury over time is the key to identifying the syndrome.",
