      "explanation": "The definitive diagnosis of neurosyphilis requires an examination of the cerebrospinal fluid (CSF). The standard serological test used for this purpose is the VDRL (Venereal Disease Research Laboratory) test performed on the CSF. While the VDRL test is a non-treponemal test and can have false positives in serum, a reactive CSF-VDRL is highly specific for neurosyphilis. Although its sensitivity is low (meaning a non-reactive test does not completely rule out the diagnosis), a positive CSF-VDRL in a patient with compatible clinical symptoms is considered diagnostic. The other non-treponemal test, RPR, is not used on CSF. The treponemal tests, such as FTA-ABS, are more sensitive but less specific when performed on CSF, as passive transfer of antibodies from the blood can cause a positive result without active CNS infection. Therefore, the CSF-VDRL remains the gold standard for diagnosis.",
