      "answerText": "(A) Buffered Charcoal Yeast Extract (BCYE) agar",
      "explanation": "Legionella pneumophila, the bacterium that causes Legionnaires' disease, is a fastidious Gram-negative rod. It has specific nutritional requirements and will not grow on standard laboratory media like blood agar or MacConkey agar. The specialized medium required for its isolation is Buffered Charcoal Yeast Extract (BCYE) agar. This medium is specifically formulated to support the growth of Legionella. It contains yeast extract as a source of nutrients, L-cysteine, which is an essential amino acid for Legionella, and ferric pyrophosphate as an iron supplement. The activated charcoal is included to absorb toxic fatty acids and other inhibitory substances that may be present in the clinical sample or the medium itself. The medium is also buffered to an optimal pH of 6.9. This specific formulation is essential for the primary isolation of Legionella from clinical specimens.",
