      "answerText": "(D) Establishment and maintenance of drug standards",
      "explanation": "Under the Constitution of India, legislative powers are divided into three lists in the Seventh Schedule: the Union List, State List, and Concurrent List. Subjects in the Concurrent List can be legislated upon by both the Central and State governments. In case of conflict, Central law prevails.\nThe establishment and maintenance of standards of drugs and poisons is included in the Concurrent List (List III). This allows both Parliament and State Legislatures to frame laws regarding drug quality, safety, and regulation. An example is the Drugs and Cosmetics Act, which sets standards applicable across India while allowing state-level enforcement.\nThe other options fall under the Union List:\n1. International immigration and quarantine involve national borders.\n2. Prevention of spread of communicable diseases between states concerns inter-state matters.\n3. Regulation of mines and oilfields is a central subject.\nTherefore, among the given options, the subject that falls under the Concurrent List is : (D) Establishment and maintenance of drug standards.",
