      "correct": "A",
      "answerText": "(A) Cohort Study",
      "explanation": "The diagram illustrates the natural history of a disease, showing the progression from the stage of susceptibility, through a subclinical phase after exposure, to the onset of clinical symptoms, and finally to an outcome such as recovery or death. A cohort study is the epidemiological study design that is best suited for studying the natural history of a disease. A cohort study is a type of observational, analytical study that follows a group (or cohort) of individuals over a period of time. In a prospective cohort study, a group of disease-free individuals is identified, their exposure status is determined, and they are then followed forward in time to observe the development (incidence) of the disease. This longitudinal design allows researchers to directly observe the sequence of events from exposure to outcome, calculate incidence rates, and determine the temporal relationship between risk factors and disease onset.",
