      "correct": "D",
      "answerText": "(D) All of the Above",
      "explanation": "A death certificate records the sequence of medical conditions that lead to a person’s death. The causes are written in a chain of events, starting with the immediate cause of death and tracing back to the underlying cause that initiated the sequence.\nIn the certificate shown in the image, the immediate cause of death is listed as cerebral hemorrhage. This indicates that the patient died due to bleeding within the brain. The certificate then identifies metastasis of the brain as the condition leading to the cerebral hemorrhage. Metastasis refers to the spread of cancer from another primary site to the brain.\nFurther down the sequence, the primary underlying disease is mentioned as breast cancer, which is the original condition that led to the spread of cancer cells to the brain. Over time, the brain metastasis caused complications that ultimately resulted in cerebral hemorrhage.\nTherefore, the death resulted from a chain of related conditions—breast cancer → brain metastasis → cerebral hemorrhage. Since all three conditions are recorded in the causal sequence, the correct answer is (D) All of the Above.",
