      "number": 151,
      "statement": "The significance of a difference between two proportions can also be evaluated using which statistical test?",
      "options": [
        "t-test",
        "Chi-square test",
        "ANOVA",
        "Correlation and regression"
      ],
      "correct": "B",
      "answerText": "(B) Chi-square test",
      "explanation": "When comparing proportions or frequencies of a categorical variable between two or more independent groups, the appropriate statistical test to determine if a significant difference exists is the chi-square (χ²) test. For example, if you want to compare the proportion of patients who responded to a new drug versus a placebo, you would use a chi-square test. The test works by comparing the observed frequencies in each category to the frequencies that would be expected if there were no real difference between the groups. A significant chi-square statistic allows you to reject the null hypothesis and conclude that the proportions are different. In contrast, the t-test (A) is used to compare the means of a continuous variable between two groups, and ANOVA (C) is used to compare the means between more than two groups.",
      "pages": [
        569,
        622
      ]
