      "answerText": "(A) A test used to assess quantitative observations before and after an intervention",
      "explanation": "A paired t-test is a statistical test used to determine if there is a significant difference between the means of two related or paired groups. The classic application of a paired t-test is in a before-and-after study design. In this design, a quantitative measurement (like blood pressure or cholesterol level) is taken on the same group of individuals before an intervention, and then the same measurement is taken again on the same individuals after the intervention. The test then analyzes the mean of the differences between the paired measurements for each subject. By looking at the differences within each individual, the test controls for inter-individual variability and is a powerful way to assess the effect of the intervention. Option C describes an unpaired or independent samples t-test. Option B describes a chi-square test.",
