      "explanation": "Consanguineous marriage, or marriage between close biological relatives, increases the risk of having offspring with autosomal recessive genetic disorders. This is because close relatives are more likely to share the same deleterious recessive alleles inherited from a common ancestor. First cousins share, on average, 1/8th of their genes. The background risk for a major congenital anomaly in the general population is about 2-3%. Consanguineous marriage approximately doubles this baseline risk. For a first-cousin marriage, the additional risk of having a child with a significant congenital or genetic disorder (primarily autosomal recessive conditions) is estimated to be around 3-5%. Therefore, the total absolute risk for an offspring of a first-cousin union is in the range of 4% to 8%. This increased risk is a key consideration in genetic counseling for consanguineous couples.",
