      "explanation": "In the tiered structure of India's rural public healthcare system, the Primary Health Centre (PHC) serves as the central hub for a defined geographical area (a Community Development Block). It is the first level of the health system to be headed by a qualified medical officer. While the Sub-centre is the most peripheral point of service delivery, the PHC is the unit responsible for the overall planning, implementation, supervision, and management of all national health programs and schemes within its jurisdiction. The medical officer of the PHC and their team are responsible for overseeing the work of the multiple Sub-centres under their purview, managing logistics, collecting and reporting health data, and providing referral support. The Anganwadi Centre is part of the ICDS scheme and focuses on nutrition, not overall health scheme management.",
