      "number": 159,
      "statement": "Vertical transmission of HIV is highest with :",
      "options": [
        "Elective cesarean section",
        "High viral RNA load",
        "Breast feeding",
        "Term delivery"
      ],
      "correct": "B",
      "answerText": "(B) High viral RNA load",
      "explanation": "Vertical transmission (or mother-to-child transmission) of HIV can occur during pregnancy, labor and delivery, or through breastfeeding. The single most important determinant of the risk of transmission is the maternal plasma HIV RNA load (viral load). There is a direct and strong correlation between the mother's viral load and the risk of transmitting the virus to her infant. A high viral load means there are more virus particles in the mother's blood and cervicovaginal secretions, which significantly increases the chance of fetal exposure and infection, particularly during delivery. The entire principle of Prevention of Mother-to-Child Transmission (PMTCT) programs is to use combination antiretroviral therapy (cART) during pregnancy to suppress the maternal viral load to undetectable levels, which reduces the transmission risk to less than 1%. Elective C-section can reduce risk but is not the highest factor.",
