      "explanation": "The diagram illustrates the sequential head positions of the Epley maneuver, also known as the canalith repositioning procedure. This maneuver is the first-line treatment for the most common cause of vertigo, which is benign paroxysmal positional vertigo (BPPV) of the posterior semicircular canal. BPPV is caused by displaced otoconia (calcium carbonate crystals) that have become free-floating in the posterior semicircular canal. The Epley maneuver is a specific series of head and body movements designed to use gravity to guide these loose otoconia out of the semicircular canal and back into the utricle, where they will no longer cause symptoms. The maneuver involves moving the patient from a sitting position, to lying down with the head turned to the affected side, then turning the head to the opposite side, rolling onto that side, and finally sitting up.",
