      "correct": "A",
      "answerText": "(A) Ptosis",
      "explanation": "Myasthenia Gravis (MG) is an autoimmune disorder characterized by antibody-mediated destruction of acetylcholine receptors at the neuromuscular junction, leading to fluctuating muscle weakness. The ocular muscles are the most frequently affected, and ocular symptoms are the initial presentation in over 50% of patients. The two most common ocular findings are ptosis (drooping of the upper eyelid) and diplopia (double vision). Ptosis in MG is caused by weakness of the levator palpebrae superioris muscle. It is characteristically asymmetric and variable, worsening with fatigue (at the end of the day) and improving with rest. The ptosis can be unilateral or bilateral and may alternate between the eyes. Diplopia is caused by weakness of one or more of the extraocular muscles. The combination of variable, fatigable ptosis and diplopia is highly suggestive of ocular myasthenia. Lagophthalmos (B) is the inability to close the eye, often seen in facial nerve palsy.",
