      "correct": "B",
      "answerText": "(B) ARDS (Acute Respiratory Distress Syndrome)",
      "explanation": "Acute pancreatitis is a major risk factor for the development of Acute Respiratory Distress Syndrome (ARDS). ARDS is a form of acute, diffuse, inflammatory lung injury characterized by a severe impairment of oxygenation and non-cardiogenic pulmonary edema. In severe pancreatitis, the release of pancreatic enzymes and inflammatory cytokines into the systemic circulation leads to a massive systemic inflammatory response syndrome (SIRS). These inflammatory mediators cause damage to the alveolar-capillary membrane in the lungs, increasing its permeability. This allows protein-rich fluid to leak into the interstitium and alveoli, causing pulmonary edema. The chest X-ray in ARDS characteristically shows diffuse, bilateral, patchy or confluent alveolar infiltrates, which is consistent with the image provided. The clinical presentation of acute breathlessness and crepitations, along with these X-ray findings in the setting of pancreatitis, is diagnostic of ARDS.",
