      "correct": "D",
      "answerText": "(D) Autosomal dominant",
      "explanation": "Achondroplasia is the most common form of skeletal dysplasia and disproportionate short stature (dwarfism). It is inherited in an autosomal dominant pattern. The condition is caused by a gain-of-function mutation in the fibroblast growth factor receptor 3 (FGFR3) gene. This mutation leads to a constitutive activation of the receptor, which severely inhibits the proliferation and differentiation of chondrocytes in the growth plates of long bones. This impairs endochondral ossification, resulting in the characteristic features of short limbs, macrocephaly, and frontal bossing. Although it is an autosomal dominant disorder, over 80% of cases of achondroplasia are the result of a de novo (new) mutation occurring in a child of unaffected, average-stature parents. When an individual with achondroplasia has children, they have a 50% chance of passing the condition on to each child.",
