      "correct": "A",
      "answerText": "(A) Serum creatinine",
      "explanation": "The Model for End-Stage Liver Disease (MELD) score is a widely used and validated scoring system that accurately predicts the 3-month mortality risk in patients with advanced liver cirrhosis. It is also used by the United Network for Organ Sharing (UNOS) to prioritize patients for liver transplantation. The original MELD score is calculated using a formula that incorporates three objective laboratory values :\n1. Serum Creatinine : A measure of kidney function, which is often impaired in advanced liver disease (hepatorenal syndrome).\n2. Serum Total Bilirubin : A measure of the liver's excretory function.\n3. International Normalized Ratio (INR) : A measure of the prothrombin time, which reflects the liver's synthetic function (production of clotting factors).\nThe MELD-Na score, a more recent update, also incorporates serum sodium. Albumin (C) is a component of the older Child-Pugh score but not the MELD score. Transaminases and alkaline phosphatase are not included.",
