      "answerText": "(A) Hypothermia",
      "explanation": "The Osborn wave, also known as the J wave, is a distinctive electrocardiogram (ECG) finding that is considered pathognomonic for hypothermia. It appears as a slow, positive deflection at the J-point, which is the junction between the end of the QRS complex and the beginning of the ST segment. This gives the J-point a humped or dome-like appearance. The amplitude of the Osborn wave is generally proportional to the degree of hypothermia, becoming more prominent as the core body temperature falls below 32°C (90°F). While J waves can occasionally be seen in other conditions such as hypercalcemia or early repolarization, their classic and most significant association is with hypothermia. The other electrolyte disturbances listed have different characteristic ECG changes (e.g., peaked T waves in hyperkalemia, U waves in hypokalemia).",
