      "explanation": "Infective endocarditis is diagnosed using the Modified Duke Criteria, which include major and minor criteria. Major blood-culture criteria are crucial for diagnosis.\nOne major criterion is positive blood cultures for typical organisms known to cause infective endocarditis. These include the HACEK group organisms (Haemophilus, Aggregatibacter, Cardiobacterium, Eikenella, Kingella). Although diagnosis usually requires two separate positive cultures, HACEK organisms are considered typical pathogens and form part of the major microbiological criteria.\nAnother major criterion is a single positive blood culture for Coxiella burnetii or a high phase I IgG antibody titer. Coxiella is highly specific for infective endocarditis, so even a single positive culture qualifies as a major criterion.\nCorynebacterium species are not typically included among the classic major organisms unless repeatedly isolated.\nThus, both HACEK organisms and Coxiella burnetii are included under major blood-culture criteria in diagnostic guidelines. Therefore, the correct answer is : (D) Both a & b",
