      "explanation": "The indications for liver transplantation in children differ from those in adults. In the pediatric population, the single most common indication for liver transplantation worldwide is biliary atresia. Biliary atresia is a rare neonatal liver disease characterized by the progressive, idiopathic fibrotic obliteration of the extrahepatic bile ducts. This leads to a complete obstruction of bile flow, resulting in cholestatic jaundice, cirrhosis, and ultimately end-stage liver failure. While the initial surgical management is a Kasai portoenterostomy to attempt to restore bile flow, this procedure is not curative for many patients. The progressive liver damage and development of portal hypertension often continue, and liver transplantation is ultimately required for long-term survival. Biliary atresia accounts for approximately half of all pediatric liver transplants.",
