      "explanation": "Infectious esophagitis is a common problem in immuno compromised patients, such as those with AIDS. The endoscopic appearance of the esophageal ulcers can be highly suggestive of the causative agent. Cytomegalovirus (CMV) esophagitis is characteristically associated with the formation of one or more large, flat, linear, or serpiginous (snake-like) ulcers, which are often located in the distal esophagus. These ulcers are typically deep and may have a well-demarcated border. In contrast, Herpes Simplex Virus (HSV) esophagitis typically causes multiple, smaller, discrete, punched-out or volcano-like ulcers in the mid-esophagus. Candida esophagitis presents as white, cottage-cheese-like plaques. Pill esophagitis usually causes a single, discrete ulcer at a site of hold-up, like the level of the aortic arch. The finding of large, linear, or serpiginous ulcers is the classic endoscopic feature of CMV infection.",
