      "explanation": "An omphalocele is a congenital ventral abdominal wall defect characterized by the herniation of abdominal viscera through the umbilical ring. The herniated organs are covered by a protective sac composed of the amnion, Wharton's jelly, and the peritoneum. The underlying embryological cause of an omphalocele is the failure of the midgut to return to the abdominal cavity after its normal physiological herniation. During early fetal development (around the 6th week of gestation), the midgut grows rapidly and herniates out into the umbilical cord. This is a normal process. The gut then rotates and should return completely to the abdominal cavity by the 10th-12th week. An omphalocele occurs when this return fails to happen, leaving some of the abdominal organs (most commonly the liver and intestines) outside the abdominal cavity, contained within the umbilical cord sac.",
