      "number": 212,
      "statement": "When a mother donates a kidney to her son, this type of transplant is referred to as what?",
      "options": [
        "Isograft",
        "Allograft",
        "Autograft",
        "Xenograft"
      ],
      "correct": "B",
      "answerText": "(B) Allograft",
      "explanation": "Transplants are classified based on the genetic relationship between the donor and the recipient. An allograft, or allogeneic transplant, is the transplantation of cells, tissues, or organs between two genetically non-identical individuals of the same species. A kidney transplant from a mother to her son falls into this category. Since the mother and son are not genetically identical (the son inherits half of his genes from his mother and half from his father), their human leukocyte antigens (HLA) will be different. This genetic disparity means the son's immune system will recognize the mother's kidney as foreign and will mount an immune response to reject it. Therefore, allograft transplantation requires lifelong immunosuppressive medication to prevent rejection. An isograft (A) is between identical twins. An autograft (C) is tissue from the same individual. A xenograft (D) is a transplant between different species.",
