      "answerText": "(A) Cloxacillin",
      "explanation": "Lactational mastitis is an infection of the breast tissue that commonly occurs in breastfeeding women, usually within the first few weeks postpartum. The most frequent causative organism is Staphylococcus aureus, which enters through cracks or fissures in the nipple.\nCloxacillin is a penicillinase-resistant penicillin and is considered the first-line treatment for uncomplicated lactational mastitis. It is effective against penicillinase-producing Staphylococcus aureus, the most common pathogen involved. The typical course is 10–14 days, along with continued breastfeeding or milk expression to prevent milk stasis. Supportive measures such as warm compresses, adequate hydration, and analgesics are also recommended.\nCefazolin is usually reserved for intravenous use in severe cases. Ceftriaxone is a broad-spectrum antibiotic and not routinely required. Ampicillin is not reliable against penicillinase-producing staphylococci.\nThus, for a lactating mother with mastitis, the first-line treatment is cloxacillin.",
