      "explanation": "Calot’s triangle (also called the cystohepatic triangle) is an important anatomical landmark in hepatobiliary surgery, especially during cholecystectomy.\nThe classical boundaries of Calot’s triangle are:\n1. Medial – Common hepatic duct\n2. Inferior (lateral) – Cystic duct\n3. Superior – Inferior surface of the liver\nThe cystic artery usually passes through this triangle, making it a key structure to identify during surgery to avoid bile duct injury.\nThe gallbladder itself is not a boundary of Calot’s triangle. Although it is anatomically related to the region, it does not form one of the defined borders of the triangle.\nTherefore, among the given options, the structure that is not a boundary of Calot’s triangle is : (D) Gall bladder",
