      "answerText": "(A) 4 months",
      "explanation": "A bidextrous grip refers to the ability of an infant to use both hands together to hold or manipulate an object. This milestone represents an important stage in the development of motor coordination and hand-eye coordination during early infancy. As the nervous system matures and muscle control improves, infants gradually begin to coordinate movements of both hands.\nAround the age of 4 months, most infants start showing the ability to grasp objects using both hands simultaneously. At this stage, babies can hold toys placed in their hands and may bring their hands together at the midline of the body. They also begin to explore objects by holding them with both hands and bringing them toward the mouth. This behavior indicates improved bilateral coordination and increased control over arm and hand movements.\nBefore this stage, infants usually show reflex grasping and limited voluntary control of their hands. As development progresses beyond 4 months, babies become more skilled at reaching, transferring objects between hands, and manipulating toys.\nTherefore, the typical age for the development of a bidextrous grip is about 4 months, making option (A) correct.",
