      "number": 227,
      "statement": "Which of the following statements accurately describes Fragile X syndrome?",
      "options": [
        "Triple nucleotide CAG sequence mutation",
        "10% female carriers mentally retarded",
        "Males have IQ 20-40",
        "Gain of function mutation"
      ],
      "correct": "B",
      "answerText": "(B) 10% female carriers mentally retarded",
      "explanation": "Fragile X syndrome is the most common inherited cause of intellectual disability and is caused by a mutation in the FMR1 gene on the X chromosome. The mutation involves an abnormal expansion of the CGG trinucleotide repeat, not CAG, in the promoter region of the gene. This expansion leads to silencing of the FMR1 gene and deficiency of the FMRP (Fragile X Mental Retardation Protein), which is important for normal brain development.\nBecause the disorder is X-linked, males are usually more severely affected than females. Males typically show moderate intellectual disability, behavioral problems, a long face, large ears, and macroorchidism after puberty. The IQ in affected males is usually around 35–50, not strictly 20–40.\nFemales who carry the mutation may show milder symptoms because they have a second normal X chromosome. Due to X-chromosome inactivation, only a portion of female carriers express the mutation. Studies show that about 10% of female carriers may have significant intellectual disability, while others may have normal intelligence or mild learning difficulties.\nTherefore, option (B) is the correct statement.",
