      "explanation": "A scissor gait is a characteristic type of spastic gait that is a hallmark of spastic cerebral palsy, particularly the spastic diplegia subtype. Cerebral palsy is a group of permanent movement disorders that appear in early childhood. In spastic diplegia, there is damage to the upper motor neurons that control the lower limbs, leading to increased muscle tone (spasticity), particularly in the hip adductor and hamstring muscles. This spasticity of the hip adductors is so pronounced that it causes the thighs and knees to be pulled tightly together and even cross over each other in a scissor-like fashion during walking. The patient walks on their toes with their knees and hips partially flexed. This abnormal gait pattern is highly characteristic of the upper motor neuron damage seen in spastic cerebral palsy.",
