      "answerText": "(B) Flexion, Adduction, Internal rotation",
      "explanation": "A posterior dislocation of the hip is the most common type of hip dislocation, accounting for approximately 90% of cases. It typically results from a high-energy traumatic force, such as a dashboard injury in a motor vehicle accident. The injury forces the femoral head out of the acetabulum in a posterior and superior direction. This displacement, combined with the unopposed pull of the surrounding muscles (particularly the gluteus medius/minimus and iliopsoas), results in a highly characteristic and pathognomonic deformity or attitude of the limb. The affected leg is held in a position of flexion, adduction, and internal rotation. The limb will also appear shortened. This specific posture is a key clinical sign that allows for immediate diagnosis upon inspection. In contrast, an anterior dislocation of the hip results in the limb being held in abduction and external rotation.",
