      "explanation": "The painful arc sign is a classic physical examination finding that is highly suggestive of shoulder impingement syndrome, which most commonly involves inflammation of the supraspinatus tendon (tendinitis) or the subacromial bursa (bursitis). The sign is elicited by asking the patient to actively abduct their arm. The test is positive if the patient experiences pain in the shoulder, not at the beginning or end of the movement, but specifically during the middle range of abduction, typically between 60 and 120 degrees. This pain occurs because, during this specific arc of motion, the greater tuberosity of the humerus passes under the acromion. If the supraspinatus tendon or the subacromial bursa is inflamed and swollen, it will be painfully compressed or impinged in the subacromial space during this mid-range of movement. The pain often subsides as the arm is abducted beyond 120 degrees because the greater tuberosity clears the acromion.",
