      "explanation": "The diagnosis of diabetes during pregnancy can be categorized as either gestational diabetes mellitus (GDM) or pre-existing overt diabetes that is first diagnosed during pregnancy. The criteria for diagnosing overt diabetes in pregnancy are the same as the standard diagnostic criteria for diabetes in non-pregnant adults. According to guidelines from the American Diabetes Association and other major bodies, a diagnosis of overt diabetes can be made if any one of the following criteria is met at the first prenatal visit : Fasting plasma glucose ≥ 126 mg/dL (7.0 mmol/L) Hemoglobin A1c ≥ 6.5% Random plasma glucose ≥ 200 mg/dL in a patient with classic symptoms of hyperglycemia. This is distinct from the diagnosis of GDM, which is defined by lower glucose thresholds on an oral glucose tolerance test (OGTT) performed later in gestation (typically 24-28 weeks).",
