      "answerText": "(C) Trichomonas vaginalis",
      "explanation": "A profuse, yellow-green, malodorous, and frothy (bubbly) vaginal discharge is the classic and pathognomonic sign of trichomoniasis, a sexually transmitted infection caused by the flagellated protozoan Trichomonas vaginalis. The characteristic appearance of the discharge is due to the inflammatory response elicited by the parasite in the vaginal and cervical mucosa. The infection is also commonly associated with significant vulvovaginal irritation, dysuria, and dyspareunia. On examination, a strawberry cervix (colpitis macularis) may be seen. This presentation is distinct from other common causes of vaginitis. Bacterial vaginosis is typically associated with a thin, greyish-white, fishy-smelling discharge. Candidiasis (B) is characterized by a thick, white, curd-like discharge with intense itching. Herpes simplex (A) causes vesicular lesions and ulcers, not a characteristic discharge.",
