      "correct": "B",
      "answerText": "(B) Deep vein thrombosis (DVT)",
      "explanation": "The estrogen component of combined oral contraceptive pills (OCPs) is known to have prothrombotic effects, increasing the risk of venous thromboembolism (VTE). According to the World Health Organization (WHO) Medical Eligibility Criteria for Contraceptive Use, a personal history of deep vein thrombosis (DVT) or pulmonary embolism (PE) is an absolute contraindication (Category 4) for the use of combined hormonal contraceptives. Initiating OCPs in a woman with a history of VTE would place her at an unacceptably high risk for a recurrent, potentially fatal, thrombotic event. Other absolute contraindications include known thrombogenic mutations, active liver disease, breast cancer, and uncontrolled hypertension with vascular disease. While conditions like diabetes with vascular complications can be a contraindication, uncomplicated diabetes is not. Chronic renal disease and a history of amenorrhea are not absolute contraindications.",
