      "correct": "A",
      "answerText": "(A) 1st trimester",
      "explanation": "The double decidual sac sign is an important and early sonographic finding that is used to confirm the presence of an intrauterine pregnancy (IUP) before the embryo or yolk sac becomes visible. It is typically seen on a transvaginal ultrasound during the first trimester, usually between 4.5 and 6 weeks of gestation. The sign consists of two concentric, echogenic (bright) rings surrounding a small, anechoic (black) gestational sac. The inner ring represents the decidua capsularis (the decidua overlying the chorionic sac) and the chorion. The outer ring represents the decidua parietalis (the decidua lining the rest of the uterine cavity). The anechoic space between these two layers is the uterine cavity. The presence of the double decidual sac sign is a highly reliable indicator of an early IUP and is crucial for helping to differentiate it from a pseudosac that can be seen with an ectopic pregnancy.",
