      "correct": "A",
      "answerText": "(A) Vaginal hysterectomy with pelvic floor repair",
      "explanation": "A third-degree uterine prolapse (procidentia) is a severe form of pelvic organ prolapse where the entire uterus descends and protrudes outside the vaginal introitus. In a postmenopausal, 60-year-old woman who is sexually active or does not wish to use a pessary, and is a suitable surgical candidate, the definitive and most appropriate management is surgical correction. The standard surgical procedure for this condition is a vaginal hysterectomy to remove the prolapsed uterus, combined with a comprehensive pelvic floor repair. The repair involves correcting associated defects such as a cystocele (anterior repair or anterior colporrhaphy) and a rectocele (posterior repair or posterior colpoperineorrhaphy). Apical suspension procedures, like sacrospinous fixation, may also be performed to support the vaginal vault. A pessary (D) is a non-surgical option suitable for women who are poor surgical candidates or who wish to avoid surgery.",
