      "number": 250,
      "statement": "The chromosome number of a partial hydatidiform mole is?",
      "options": [
        "46 XX",
        "45 ΧΟ",
        "46 XXY",
        "69 XXX"
      ],
      "correct": "D",
      "answerText": "(D) 69 XXX",
      "explanation": "A partial hydatidiform mole is a type of gestational trophoblastic disease characterized by abnormal placental development and the presence of an abnormal fetus. The genetic cause of a partial mole is dispermy, which is the fertilization of a single, apparently normal ovum (containing 23,X chromosomes) by two separate sperm (each containing either 23,X or 23,Y chromosomes). This results in a triploid conceptus, which has a total of 69 chromosomes. The resulting karyotype can be 69,XXY, 69,XXX, or, very rarely, 69,XYY. The most common karyotype is 69,XXY. Therefore, 69,XXX is a correct example of the triploid chromosome number found in a partial mole. This is in contrast to a complete mole, which is diploid (usually 46,XX) and entirely of paternal origin, with no fetal tissue present.",
