      "correct": "A",
      "answerText": "(A) 11-13 weeks",
      "explanation": "The nuchal translucency (NT) measurement is a key component of the first-trimester screening for fetal aneuploidies, particularly Down syndrome (Trisomy 21). The NT is the sonographic appearance of a collection of fluid under the skin behind the fetal neck. This measurement is performed using a transabdominal or transvaginal ultrasound during a very specific and narrow gestational window. The optimal time to measure the NT is between 11 weeks and 13 weeks + 6 days of gestation. During this period, the fetal crown-rump length (CRL) should be between 45 mm and 84 mm. An increased NT thickness during this specific timeframe is associated with an increased risk of chromosomal abnormalities, congenital heart defects, and other genetic syndromes. The measurement is not valid or interpretable outside of this specific gestational window.",
