      "explanation": "Ulipristal acetate is a selective progesterone receptor modulator (SPRM) that is used for two main indications : emergency contraception and the medical management of uterine fibroids. For its use as an oral emergency contraceptive, ulipristal acetate is administered as a single oral dose of 30 mg. It is most effective when taken as soon as possible after unprotected intercourse but can be used up to 120 hours (5 days) later. Its primary mechanism of action for emergency contraception is to inhibit or delay ovulation by blocking the effects of progesterone on the luteinizing hormone (LH) surge. It is considered one of the most effective oral emergency contraceptive options available. The higher dose of 300 mg is related to its use as an abortifacient (in combination with other drugs), not as an emergency contraceptive.",
