    {
      "number": 263,
      "statement": "What is the primary source of amniotic fluid after 20 weeks of gestation?",
      "options": [
        "Ultrafiltrate and maternal plasma",
        "Fetal urine",
        "Fetal lung fluid",
        "Fetal skin"
      ],
      "correct": "B",
      "answerText": "(B) Fetal urine",
      "explanation": "The volume and composition of amniotic fluid change throughout pregnancy. In the first trimester, the amniotic fluid is primarily an ultrafiltrate of maternal plasma that crosses the amnion. However, as the pregnancy progresses into the second and third trimesters, the dynamics change significantly. After approximately 20 weeks of gestation, the single largest contributor to the volume of amniotic fluid is fetal urine. The fetal kidneys become functional and begin to produce a large volume of hypotonic urine, which is voided into the amniotic sac. The fetus then swallows this fluid, which is absorbed from the GI tract, and the cycle continues. This process of fetal urination and swallowing is the primary mechanism for regulating amniotic fluid volume in the latter half of pregnancy. This is why conditions that prevent fetal urination (e.g., bilateral renal agenesis) lead to severe oligohydramnios.",
      "pages": [
        581,
        648
      ]
    },
    {
      "number": 264,
      "statement": "What is the maximum allowable dose of PGF₂α (Prostaglandin F2 alpha) for managing postpartum hemorrhage (PPH)?",
      "options": [
        "20 µg",
        "200 µg",
        "2 mg",
        "20 mg"
      ],
      "correct": "C",
      "answerText": "(C) 2 mg",
      "explanation": "Prostaglandin F2-alpha (PGF2α), in the form of its synthetic analogue carboprost tromethamine, is a potent uterotonic agent used as a second-line treatment for postpartum hemorrhage (PPH) due to uterine atony that is refractory to oxytocin and methylergometrine. Carboprost is administered via deep intramuscular (IM) injection. The standard single dose is 250 micrograms (µg). This dose can be repeated every 15 to 90 minutes if uterine tone does not improve and bleeding continues. However, there is a maximum cumulative dose that should not be exceeded due to the risk of significant side effects (such as bronchospasm, hypertension, and severe diarrhea). The total maximum dose of carboprost that can be administered is 2 milligrams (mg), which is equivalent to a total of eight 250 µg injections.",
      "pages": [
        586,
        648
      ]
    }
