      "explanation": "The image displays excoriated papules and burrows in the web spaces of the fingers. This, combined with the primary symptom of intense pruritus (itching) that is classically worse at night, is the hallmark presentation of scabies. Scabies is a highly contagious skin infestation caused by the mite Sarcoptes scabiei var. hominis. The pregnant female mite burrows into the stratum corneum of the epidermis to lay her eggs. The characteristic lesions—small erythematous papules and thin, thread-like burrows—are most commonly found in specific predilection sites, including the interdigital web spaces, wrists, axillae, and genital area. The intense itching is a delayed-type hypersensitivity reaction to the mites, their eggs, and their feces. The diagnosis is confirmed by identifying the mite, eggs, or fecal pellets (scybala) on a skin scraping.",
