      "correct": "B",
      "answerText": "(B) Alopecia areata",
      "explanation": "Alopecia areata is an autoimmune disorder characterized by sudden, well-defined patches of non-scarring hair loss on the scalp or other hair-bearing areas. In the image, the lesion shows a smooth, round or oval bald patch with normal-appearing skin, which is a classic feature of alopecia areata. There is no scaling, inflammation, or broken hairs, helping to differentiate it from fungal infections like tinea capitis. Unlike trichotillomania, where hairs are broken at different lengths due to pulling, alopecia areata shows complete hair loss in the affected area. Sebaceous cysts present as localized swellings rather than bald patches. The condition results from T-cell–mediated immune attack on hair follicles, leading to hair shedding in the anagen phase. Nail pitting may be associated. Hair regrowth is possible and often spontaneous, although relapses are common. Thus, the smooth, sharply demarcated patch seen in the image is most consistent with alopecia areata.",
