      "correct": "A",
      "answerText": "(A) Herpes zoster",
      "explanation": "The image displays a skin rash characterized by a cluster of vesicles on an erythematous base. The key feature of this rash is its distribution : it is strictly unilateral and appears in a linear, band-like pattern that corresponds to a dermatome (the area of skin supplied by a single spinal nerve). This dermatomal distribution is the pathognomonic sign of Herpes Zoster, commonly known as shingles. Herpes zoster is caused by the reactivation of the varicella-zoster virus (VZV), the same virus that causes chickenpox. After the primary chickenpox infection, the virus becomes latent in the dorsal root ganglia. Years later, it can reactivate and travel down the sensory nerve to cause this characteristic painful, vesicular rash in the dermatome supplied by that nerve. The rash does not cross the midline, which is a key feature distinguishing it from other vesicular eruptions like disseminated herpes simplex or chickenpox.",
