      "explanation": "The image shows well-defined erythematous plaques on the scalp with scaling, atrophy, and areas of scarring alopecia, which are characteristic features of Discoid Lupus Erythematosus (DLE). DLE is a chronic autoimmune cutaneous form of lupus erythematosus that primarily affects sun-exposed areas such as the face, scalp, and ears. Lesions typically begin as red or pink scaly plaques that gradually develop central atrophy, depigmentation, and permanent scarring.\nWhen the scalp is involved, DLE often leads to scarring alopecia, meaning the hair follicles are destroyed and hair loss becomes permanent. The lesions may also show follicular plugging and thick adherent scales, which are common diagnostic clues.\nThis condition must be differentiated from other options. Vitiligo and leukoderma present with depigmented patches but do not cause scaling or scarring alopecia. Piebaldism is a congenital disorder characterized by stable depigmented patches present since birth. The inflammatory, scaly, and scarring nature of the lesion seen in the image strongly supports DLE as the correct diagnosis.",
